using System;using System.Collections.Generic;public class Solution{public IList<IList<int>> FourSum(int[]a,int t){Array.Sort(a);var o=new List<IList<int>>();int n=a.Length;for(int i=0;i<n-3;i++){if(i>0&&a[i]==a[i-1])continue;for(int j=i+1;j<n-2;j++){if(j>i+1&&a[j]==a[j-1])continue;int l=j+1,r=n-1;while(l<r){long s=(long)a[i]+a[j]+a[l]+a[r];if(s<t)l++;else if(s>t)r--;else{o.Add(new List<int>{a[i],a[j],a[l],a[r]});int x=a[l],y=a[r];while(l<r&&a[l]==x)l++;while(l<r&&a[r]==y)r--;}}}}return o;}}
